<!DOCTYPE html>
<html lang="zh-CN">
<head>
<script id="endfield-opening-auto-dispose">
// 前端 AGENT：开局面板只用于尚未发送消息的第 0 楼。
// 点击「开始」仅保存变量/填入输入框，不关闭；出现后续消息才卸载。
// 不删聊天消息、不清变量、不改原始开场标记；重渲染时会再次检查。
// 卸载 iframe 会结束其中的动画与计时器，比仅隐藏 main 更能释放资源。
(() => {
  let observer, timer, disposed=false;
  const frame=window.frameElement;
  // 只允许卸载本页面自己的 iframe；独立浏览器预览保持可见。
  if(!frame || window.parent===window) return;
  let host;
  try { host=window.parent.document; } catch { return; }
  const cleanup=()=>{
    observer?.disconnect();
    window.clearInterval(timer);
  };
  function check(){
    if(disposed || !frame.isConnected) { cleanup(); return; }
    const message=frame.closest('.mes[mesid]');
    if(!message || message.getAttribute('mesid')!=='0') return;
    const chat=message.closest('#chat');
    if(!chat) return;
    // 检查同一聊天容器，避免把聊天外的预览消息误判为已开始。
    const started=Array.from(chat.querySelectorAll('.mes[mesid]'))
      .some(node=>Number(node.getAttribute('mesid'))>0);
    if(!started) return;
    disposed=true;
    cleanup();
    // 仅移除自己的呈现容器，不移除第 0 楼消息及其他终端组件。
    frame.remove();
  }
  const chat=frame.closest('#chat');
  if(chat){
    observer=new MutationObserver(check);
    observer.observe(chat,{childList:true,subtree:true,attributes:true,attributeFilter:['mesid']});
  }
  // 某些宿主会先创建 iframe 再挂入聊天；低频检查覆盖延迟挂载。
  timer=window.setInterval(check,1000);
  window.addEventListener('pagehide',cleanup,{once:true});
  check();
})();
</script>

