nav{
  position:relative;
  z-index:2;
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:8px;
  margin-top:14px;
  padding-top:12px;
  border-top:1px solid #27272b;
}
button{
  position:relative;
  overflow:hidden;
  padding:6px 16px;
  cursor:pointer;
  border:1px solid #fffa80;
  border-radius:1px;
  background:#fffa80;
  color:#121214;
  font-size:12.5px;
  font-weight:700;
  letter-spacing:.4px;
  box-shadow:0 0 10px rgba(255,250,128,0.22);
  transition:
    background-color .2s cubic-bezier(.4,0,.2,1),
    color .2s ease,
    border-color .2s ease,
    box-shadow .2s ease,
    transform .1s ease;
}
button:not(.secondary):not(:disabled){
  animation:ef-btn-breathe 2.6s ease-in-out infinite;
}
@keyframes ef-btn-breathe{
  0%,100%{box-shadow:0 0 8px rgba(255,250,128,0.2)}
  50%{box-shadow:0 0 16px rgba(255,250,128,0.42)}
}
button::after{
  content:'';
  position:absolute;
  top:0;
  left:-120%;
  width:60%;
  height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,0.45),transparent);
  transform:skewX(-22deg);
  transition:left .4s ease;
  pointer-events:none;
}
button:not(:disabled):hover::after{
  left:150%;
}
button:not(:disabled):active{
  transform:translateY(1px) scale(.985);
}
button.secondary{
  background:#1f1f23;
  border-color:#46464f;
  color:#d4d4d8;
  font-weight:600;
  box-shadow:none;
  animation:none;
}
#retry{
  margin-left:auto;
}
@media(hover:hover) and (pointer:fine){
  button:not(:disabled):hover{
    background:#fffa80;
    color:#121214;
    border-color:#fffa80;
    box-shadow:0 0 14px rgba(255,250,128,0.5),0 4px 10px rgba(0,0,0,0.35);
  }
}
button:disabled{
  opacity:.4;
  cursor:default;
  box-shadow:none;
  animation:none;
}

