let locState = {
  type: 'major', // 'major' | 'free' | 'custom'
  major: '四号谷地',
  sub: '枢纽区',
  waypoint: '集成核心区域',
  custom: ''
};

function getSelectedLocationText(){
  if (locState.type === 'free') return '';
  if (locState.type === 'standalone') {
    return locState.standaloneName || '终末地工业｜帝江号';
  }
  if (locState.type === 'custom') {
    return locState.custom.trim() ? ('自定义场景：' + locState.custom.trim()) : '';
  }
  return locState.major + ' · ' + locState.sub + ' · ' + locState.waypoint;
}

function updateLocationBadgeAndIntel(){
  const badge = el('ef-loc-target-badge');
  const intelWrap = el('ef-loc-intel');
  const intelText = el('ef-loc-intel-text');
  if (!badge) return;

  if (locState.type === 'free') {
    badge.textContent = '当前选取：自由开局';
    badge.className = 'ef-loc-target-badge is-free';
    if (intelWrap) intelWrap.style.display = 'flex';
    if (intelText) intelText.textContent = '不强制开场场景，由AI随机ROLL。';
    return;
  }
  if (locState.type === 'standalone') {
    const name = locState.standaloneName || '终末地工业｜帝江号';
    badge.textContent = '当前选取：' + name;
    badge.className = 'ef-loc-target-badge';
    if (intelWrap) intelWrap.style.display = 'flex';
    if (intelText) intelText.textContent = 'O.M.V.帝江号：终末地工业轨道总部，源石动力空天作业船，被称为“人类科学技术的至高结晶”。兼具协议系统总控、工业生产、科研维护与干员生活保障功能。';
    return;
  }
  if (locState.type === 'custom') {
    const val = locState.custom.trim() || '未输入';
    badge.textContent = '当前选取：自定义 · ' + val;
    badge.className = 'ef-loc-target-badge';
    if (intelWrap) intelWrap.style.display = 'flex';
    if (intelText) intelText.textContent = '手动指定坐标场景，剧情将强制切入该自定义地点。';
    return;
  }

  badge.textContent = '当前选取：' + locState.major + ' · ' + locState.sub + ' · ' + locState.waypoint;
  badge.className = 'ef-loc-target-badge';

  const subList = MAP_DATA[locState.major]?.[locState.sub] || [];
  const found = subList.find(item => item.name === locState.waypoint);
  if (intelWrap && intelText) {
    if (found?.summary) {
      intelWrap.style.display = 'flex';
      intelText.textContent = found.summary;
    } else {
      intelWrap.style.display = 'none';
    }
  }
}

function renderLocationModule(){
  const majorChips = el('ef-loc-major-chips');
  const subRow = el('ef-loc-sub-row');
  const subTitle = el('ef-loc-sub-title');
  const subChips = el('ef-loc-sub-chips');
  const wpRow = el('ef-loc-waypoint-row');
  const wpChips = el('ef-loc-waypoint-chips');
  const customRow = el('ef-loc-custom-row');
  const customInput = el('ef-loc-custom-input');
  if (!majorChips) return;

  // 1. 大区域 Chips
  majorChips.replaceChildren();
  const majorList = [
    { id: 'dijiang', label: '终末地工业｜帝江号', type: 'standalone' },
    { id: '四号谷地', label: '四号谷地', type: 'major' },
    { id: '武陵', label: '武陵', type: 'major' },
    { id: 'free', label: '自由开局 (不锚定)', type: 'free' },
    { id: 'custom', label: '自定义地点...', type: 'custom' }
  ];

  majorList.forEach(item => {
    const btn = document.createElement('div');
    const isAct = (locState.type === item.type && (item.type !== 'major' || locState.major === item.id));
    btn.className = 'ef-loc-chip' + (isAct ? ' is-active' : '');
    btn.textContent = item.label;
    btn.addEventListener('click', () => {
      if (item.type === 'standalone') {
        locState.type = 'standalone';
        locState.standaloneName = '终末地工业｜帝江号';
      } else if (item.type === 'major') {
        locState.type = 'major';
        locState.major = item.id;
        const subs = Object.keys(MAP_DATA[item.id] || {});
        if (!subs.includes(locState.sub)) {
          locState.sub = subs[0] || '';
        }
        const wps = MAP_DATA[item.id]?.[locState.sub] || [];
        if (!wps.some(w => w.name === locState.waypoint)) {
          locState.waypoint = wps[0]?.name || '';
        }
      } else if (item.type === 'free') {
        locState.type = 'free';
      } else if (item.type === 'custom') {
        locState.type = 'custom';
        setTimeout(() => customInput?.focus(), 50);
      }
      renderLocationModule();
    });
    majorChips.appendChild(btn);
  });

  // 2. 显示控制：帝江号作为独立直达条目，不需要 LEVEL 1 2 3 分级
  if (locState.type === 'standalone') {
    if (subRow) subRow.style.display = 'none';
    if (wpRow) wpRow.style.display = 'none';
    if (customRow) customRow.style.display = 'none';
    updateLocationBadgeAndIntel();
    return;
  }

  if (locState.type === 'free') {
    if (subRow) subRow.style.display = 'none';
    if (wpRow) wpRow.style.display = 'none';
    if (customRow) customRow.style.display = 'none';
    updateLocationBadgeAndIntel();
    return;
  }

  if (locState.type === 'custom') {
    if (subRow) subRow.style.display = 'none';
    if (wpRow) wpRow.style.display = 'none';
    if (customRow) customRow.style.display = 'block';
    if (customInput) customInput.value = locState.custom;
    updateLocationBadgeAndIntel();
    return;
  }

  // major 模式
  if (subRow) subRow.style.display = 'block';
  if (wpRow) wpRow.style.display = 'block';
  if (customRow) customRow.style.display = 'none';

  // 3. 子区域 Chips
  if (subTitle) subTitle.textContent = 'LEVEL 2 // SECTOR (' + locState.major + ' · 子区域)';
  subChips.replaceChildren();
  const subNames = Object.keys(MAP_DATA[locState.major] || {});
  subNames.forEach(sName => {
    const sBtn = document.createElement('div');
    sBtn.className = 'ef-loc-chip' + (locState.sub === sName ? ' is-active' : '');
    sBtn.textContent = sName;
    sBtn.addEventListener('click', () => {
      locState.sub = sName;
      const wps = MAP_DATA[locState.major]?.[sName] || [];
      locState.waypoint = wps[0]?.name || '';
      renderLocationModule();
    });
    subChips.appendChild(sBtn);
  });

  // 4. 具体地点 Chips
  wpChips.replaceChildren();
  const waypoints = MAP_DATA[locState.major]?.[locState.sub] || [];
  waypoints.forEach(wp => {
    const wpBtn = document.createElement('div');
    wpBtn.className = 'ef-loc-chip' + (locState.waypoint === wp.name ? ' is-active' : '');
    wpBtn.textContent = wp.name;
    wpBtn.title = wp.summary || '';
    wpBtn.addEventListener('click', () => {
      locState.waypoint = wp.name;
      renderLocationModule();
    });
    wpChips.appendChild(wpBtn);
  });

  updateLocationBadgeAndIntel();
}

const BOOK='エンドフィールド v2.0';
